// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address nonOwner, address newOwner1, address newOwner2) public {
        vm.assume(nonOwner != c.owner());
        vm.assume(newOwner1 != nonOwner);
        vm.assume(newOwner2 != newOwner1);
        vm.assume(newOwner2 != nonOwner);

        vm.prank(nonOwner);
        try c.transferOwnership(newOwner1) {} catch {}

        address ownerAfterFirstCall = c.owner();

        vm.prank(nonOwner);
        try c.transferOwnership(newOwner2) {} catch {}

        address ownerAfterSecondCall = c.owner();

        assertTrue(ownerAfterFirstCall == ownerAfterSecondCall);
    }
}
